/**
 * Form indexes of the Arabic adapter: a written form (without its vowels) → the readings a source gives it, each WITH its vowels.
 * The same design as the Russian, Greek and Hebrew stores (src/adapters/russian/index-store.ts).
 *
 * Indexes, all GENERATED by scripts/ar-build-index.mts from the Wiktionary extract of kaikki.org (CC BY-SA 4.0):
 *   ar-core            the closed classes and the commonest lemmas with every form of theirs, compiled into the analyser
 *                      (arabic/generated/core.ts) so that a host with no assets still reads ordinary prose.
 *   kaikki-ar-tables   every conjugation and declension row and every form-of page of the extract, SHARDED
 *                      (public/lexicon/ar/standard/), loaded on demand (arabic/shards.ts) and installed beside the core.
 *
 * Keys are `arKey(form)` (text.ts): no vowel marks, no tatweel; hamza seats, ة and ى kept. Arabic is printed without its vowels, so
 * one key usually holds several readings (كتب: كَتَبَ he wrote, كُتِبَ it was written, كُتُب books …): every row carries the vowels the
 * source gives the form (`vocal`, text.ts packVocal), and the analyser compares them with whatever vowels the page printed.
 * `loose` maps a loosely spelled key (hamza left off the alif, ى for ي, ه for ة) to the keys it may stand for.
 *
 * The index holds WORDS WITHOUT CLITICS: وبالكتاب is found by the analyser as و + ب + ال + كتاب (arabic/clitics.ts), never stored.
 * A row never invents anything: lemma, tags and vowels are the source's, verbatim.
 */
import { applyVocal, arLoose, hasBorrowedLetter } from './text';

/**
 * One lexeme:
 *   head    the headword as the source writes it, fully vocalized, NFC ("كِتَاب", "كَتَبَ", "مَكْتَبَة"). It is the lexeme's identity:
 *           عِلْم (knowledge), عَلَم (flag) and عَلِمَ (to know) are three lexemes that share the key علم.
 *   gloss   the source's first gloss, shortened ("book")
 *   pos     UPOS (NOUN, PROPN, VERB, ADJ, ADV, PRON, DET, ADP, CONJ, SCONJ, PART, NUM, INTJ)
 *   lex     the features of the lexeme itself, as "Key=Value|Key=Value" (sorted by key): `Gender` of a noun, `Form` of a verb
 *           (I … X, Iq, IIq …), `Decl` (Trip, Dip, Indecl), `Reg` (Cla when every sense is marked Classical, archaic or obsolete;
 *           Msa when the source marks the word as modern only); "" when none
 *   count   an ESTIMATE of how common the lexeme is (see scripts/ar-build-index.mts): it orders readings, nothing more
 *   root    the root as the source gives it, radicals in order, separated by spaces ("ك ت ب"); absent when the source names none
 */
export type ArLemmaRow = [head: string, gloss: string, pos: string, lex: string, count: number, root?: string];

/** One reading of a form: [index into `lemmaIds`, index into `codes`, the form's vowels (text.ts packVocal; absent = the source gave none)]. */
export type ArFormRow = [lemma: number, code: number, vocal?: string];

export interface ArabicFormIndex {
  schema: 1;
  id: 'ar-core' | 'kaikki-ar-tables' | string;
  /** A SHARD of a larger index: the prefix of the letters its keys share (text.ts `arShardLetters`); shards of one id sit side by side. */
  shard?: string;
  source: { label: string; licence: string; url: string; lastModified?: string; retrieved?: string; sha256?: string; note?: string };
  built: string;
  /**
   * The tag bundles rows refer to: the source's own labels for the form, verbatim, sorted and joined with "|"
   * ("active|indicative|masculine|past|perfective|singular|third-person", "construct|nominative|singular|triptote" …).
   * arabic/tags.ts turns a bundle into features; nothing is interpreted at build time.
   */
  codes: string[];
  /** The lemma ids rows refer to: "<vocalized headword>|<POS>", with "|2", "|3" … for a further entry with the same vocalized headword and part of speech. */
  lemmaIds: string[];
  lemmas: Record<string, ArLemmaRow>;
  forms: Record<string, ArFormRow[]>;
  /** loose key → the keys of this index that it may stand for (only keys that differ from their own loose fold are listed). */
  loose: Record<string, string[]>;
  stats?: Record<string, number>;
}

export interface ArIndexHit {
  index: ArabicFormIndex;
  /** The key the reading is filed under (differs from the looked-up key when `viaLoose`). */
  key: string;
  lemmaId: string;
  lemma: ArLemmaRow;
  /** The source's tag bundle for the form. */
  code: string;
  /** The packed vowels of the form (text.ts), "" when the source gave none. */
  vocal: string;
  /** The form with its vowels (`applyVocal(key, vocal)`). */
  vocalized: string;
  /** True when the text's spelling was loose (a hamza left off, ى for ي, ه for ة) and this reading restores it; the reading says so. */
  viaLoose: boolean;
}

const INSTALLED = new Map<string, ArabicFormIndex>();
const storeKey = (id: string, shard?: string): string => (shard ? `${id}#${shard}` : id);

/** Installs an index, or one shard of one (keyed by id and shard); re-installing replaces. */
export function installArabicIndex(idx: ArabicFormIndex): void { INSTALLED.set(storeKey(idx.id, idx.shard), idx); }
export function uninstallArabicIndex(id: string, shard?: string): boolean { return INSTALLED.delete(storeKey(id, shard)); }
export function installedArabicIndexes(): ArabicFormIndex[] { return [...INSTALLED.values()]; }
/** Forgets every installed index (or shard) for which `keep(id, shard)` is not true. */
export function resetArabicIndexes(keep?: (id: string, shard?: string) => boolean): void {
  for (const [k, idx] of [...INSTALLED.entries()]) if (!keep?.(idx.id, idx.shard)) INSTALLED.delete(k);
}

function rowsOf(index: ArabicFormIndex, key: string, viaLoose: boolean, out: ArIndexHit[], seen: Set<string>): void {
  for (const row of index.forms[key] ?? []) {
    const lemmaId = index.lemmaIds[row[0]];
    const lemma = index.lemmas[lemmaId];
    const code = index.codes[row[1]];
    if (!lemma || code === undefined) continue;
    // the core and a shard may both hold the same reading: it is listed once
    const sig = `${key}\t${lemmaId}\t${code}\t${row[2] ?? ''}`;
    if (seen.has(sig)) continue;
    seen.add(sig);
    out.push({ index, key, lemmaId, lemma, code, vocal: row[2] ?? '', vocalized: applyVocal(key, row[2]), viaLoose });
  }
}

/**
 * The readings of a key across the installed indexes: the form as written first, then the forms the key may loosely stand for
 * (marked `viaLoose`). Both lists are always given: اكل may be أَكَلَ printed without its hamza, and only the reader of the sentence
 * can say. Order within each list: the lemma's count, highest first.
 */
export function lookupArabicForm(key: string): ArIndexHit[] {
  const direct: ArIndexHit[] = [];
  const restored: ArIndexHit[] = [];
  const seen = new Set<string>();
  for (const index of INSTALLED.values()) rowsOf(index, key, false, direct, seen);
  const folded = arLoose(key);
  // a borrowed letter (ڤيديو, پاريس): the dictionary spells the word with the Arabic letter, so the fold itself is a key to try
  if (folded !== key && hasBorrowedLetter(key)) for (const index of INSTALLED.values()) rowsOf(index, folded, true, restored, seen);
  for (const index of INSTALLED.values()) for (const k of index.loose[folded] ?? []) if (k !== key) rowsOf(index, k, true, restored, seen);
  const byCount = (a: ArIndexHit, b: ArIndexHit): number => b.lemma[4] - a.lemma[4];
  return [...direct.sort(byCount), ...restored.sort(byCount)];
}

/** True when some installed index has the key as written. */
export function hasArabicForm(key: string): boolean {
  for (const index of INSTALLED.values()) if (index.forms[key]?.length) return true;
  return false;
}

/** The lemma row of an id, from any installed index (or the one given). */
export function lookupArabicLemma(lemmaId: string, index?: ArabicFormIndex): ArLemmaRow | undefined {
  if (index) return index.lemmas[lemmaId];
  for (const idx of INSTALLED.values()) { const r = idx.lemmas[lemmaId]; if (r) return r; }
  return undefined;
}

/** The vocalized headword of a lemma id: "كِتَاب|NOUN" → "كِتَاب", "كُتَّاب|NOUN|2" → "كُتَّاب". */
export const lemmaOfId = (lemmaId: string): string => lemmaId.split('|')[0];

/** The lexeme features of a lemma row as a record ("Form=I|Reg=Cla" → { Form: 'I', Reg: 'Cla' }). */
export function lexOf(row: ArLemmaRow | undefined): Record<string, string> {
  const out: Record<string, string> = {};
  for (const kv of (row?.[3] ?? '').split('|')) { const i = kv.indexOf('='); if (i > 0) out[kv.slice(0, i)] = kv.slice(i + 1); }
  return out;
}
